/**
 * dsh-ui-ptc browser half — generated by dsh-ui-suite/scripts/build.mjs.
 *
 * One component per package: the runtime below is the same code every suite
 * package carries, so installing this package alone works, and the component
 * mounts under the same failure boundary as the rest of the suite.
 *
 * Edit src/component.js (or the runtime in dsh-ui-copy/src/core), then rerun
 * the build.
 */

/**
 * dsh-ui-copy runtime — the one place where a component gets its services.
 *
 * The suite exists because a dozen UI plugins used to poll the same document
 * with a dozen MutationObservers, each injecting its own <style> and each
 * guessing whether the shipped DOM had already mounted. This runtime gives them
 * one observer, one frame budget, one style registry and one failure boundary:
 *
 *   - `observe(pass)` registers a DOM pass; every registered pass runs in a
 *     single rAF-throttled sweep, and one crashing pass never stops the rest.
 *   - `style(id, css)` registers a sheet by component id, so a sheet can be
 *     replaced without touching the DOM and no sheet is ever written twice.
 *   - `mount(key, factory)` calls a component factory under `try`/`catch`, so a
 *     host upgrade that removes a slot, or a disabled external bundle, disables
 *     one component instead of the whole suite.
 *   - `option(name, fallback)` reads the config the host half injected, which is
 *     the only channel a browser bundle has: a boot-graph row arrives as
 *     `{ id, url, rev }` and `apply(ctx, config)` always sees an empty config.
 *
 * Component contract — a component is a top-level function in the built bundle:
 *
 *     function dshuiComponent_<key>(rt) {
 *       if (rt.config.enabled === false) return
 *       ...
 *     }
 *
 * Components never touch `window.__ModuleLoader__`, never build their own
 * MutationObserver, and never write a literal colour, radius, gap, size,
 * duration or shadow: those live in `lib/styles/tokens.css` as `--dshui-*`.
 */

/**
 * Build the runtime handed to every component.
 *
 * @param env - `{ ctx, require }` from the bundle factory.
 * @param config - the host half's injected `window.__DSHUI_CONFIG__` object.
 */
function dshuiCreateRuntime(env, config) {
  var ctx = env.ctx
  var load = env.require
  // The token contract lives on `body` (see lib/styles/tokens.css), so a token
  // is read there rather than from the document root.
  var root = document.body !== null ? document.body : document.documentElement
  var suiteConfig = isRecord(config) ? config : {}

  /** Component state: key -> `{ enabled, options }`. */
  var components = Object.create(null)

  /** Every DOM pass registered by an enabled component. */
  var passes = []

  /** Owned cleanups, run by `dispose`. */
  var cleanups = []

  /** A frame has been requested but has not run yet. */
  var scheduled = false

  function isRecord(value) {
    return typeof value === 'object' && value !== null && !Array.isArray(value)
  }

  function merge(base, over) {
    var out = {}
    var key
    for (key in base) if (Object.prototype.hasOwnProperty.call(base, key)) out[key] = base[key]
    for (key in over) if (Object.prototype.hasOwnProperty.call(over, key)) out[key] = over[key]
    return out
  }

  /**
   * A component key as the schema spells it: `session-delete` -> `sessionDelete`.
   *
   * Component ids stay hyphenated (they match `<nn>-<key>.js` and the sheet
   * names), while the host schema uses camelCase field names, so every lookup
   * tries both spellings rather than making each component remember which one
   * its block landed under.
   */
  function schemaKeyOf(key) {
    return String(key).replace(/-([a-z0-9])/g, function (_, letter) {
      return letter.toUpperCase()
    })
  }

  /**
   * The config block for one component.
   *
   * Accepts both shapes a config can arrive in — a flat `{ quota: { … } }` map
   * and the same value nested under `components` — and both spellings, because
   * the host half writes camelCase while components name themselves with
   * hyphens.
   */
  function componentConfig(key) {
    var names = [key, schemaKeyOf(key)]
    var found = null
    for (var index = 0; index < names.length; index += 1) {
      if (isRecord(suiteConfig[names[index]])) {
        found = suiteConfig[names[index]]
        break
      }
    }
    var nestedSource = isRecord(suiteConfig.components) ? suiteConfig.components : null
    var nested = null
    if (nestedSource !== null) {
      for (var position = 0; position < names.length; position += 1) {
        if (isRecord(nestedSource[names[position]])) {
          nested = nestedSource[names[position]]
          break
        }
      }
    }
    return merge(nested || {}, found || {})
  }

  function warn(key, message) {
    console.warn('[ui-copy/' + key + '] ' + message)
  }

  function fail(key, error) {
    console.error('[ui-copy/' + key + ']', error)
  }

  function request() {
    if (scheduled) return
    scheduled = true
    requestAnimationFrame(run)
  }

  function run() {
    scheduled = false
    if (document.body === null) return
    var snapshot = passes.slice()
    for (var index = 0; index < snapshot.length; index += 1) {
      var entry = snapshot[index]
      if (entry === undefined) continue
      try {
        entry.pass()
      } catch (error) {
        fail(entry.key, error)
        var position = passes.indexOf(entry)
        if (position !== -1) passes.splice(position, 1)
      }
    }
  }

  function sheetById(id) {
    return document.head.querySelector('style[data-dshui-sheet="' + String(id).replace(/["\\]/g, '\\$&') + '"]')
  }

  function installStyle(id, css) {
    var existing = sheetById(id)
    if (existing !== null) {
      existing.textContent = css
      return function () {
        if (existing.parentNode !== null) existing.parentNode.removeChild(existing)
      }
    }
    var style = document.createElement('style')
    style.setAttribute('data-dshui-sheet', id)
    style.textContent = css
    document.head.appendChild(style)
    return function () {
      if (style.parentNode !== null) style.parentNode.removeChild(style)
    }
  }

  function requireExternal(name) {
    try {
      return load(name)
    } catch (error) {
      fail('bundle', 'cannot load "' + name + '": ' + String((error && error.message) || error))
      return null
    }
  }

  /** The object handed to one component factory. */
  function componentApi(key, options) {
    return {
      /* ---- identity -------------------------------------------------- */
      key: key,
      ctx: ctx,
      suite: suiteConfig,

      /* ---- configuration --------------------------------------------- */
      /** This component's own block. `enabled` is already honoured by `mount`. */
      config: options,
      option: function (name, fallback) {
        var value = options[name]
        return value === undefined ? fallback : value
      },
      /** Another component's state, for components that depend on a sibling. */
      component: function (other) {
        return components[other] || { enabled: false, options: {} }
      },
      /** The current theme name, read from the same attribute the host themes on. */
      theme: function () {
        return document.body !== null && document.body.hasAttribute('data-ds-dark-theme') ? 'dark' : 'light'
      },

      /* ---- host services --------------------------------------------- */
      /** An external package, or `null` when it is not in this boot graph. */
      require: requireExternal,
      /** Run a host effect, or run the body directly when the seam is absent. */
      effect: function (body, label) {
        try {
          if (ctx && typeof ctx.effect === 'function') return ctx.effect(body, label || key)
        } catch (error) {
          fail(key, error)
          return undefined
        }
        try {
          return body()
        } catch (error) {
          fail(key, error)
          return undefined
        }
      },

      /* ---- document --------------------------------------------------- */
      /** Register a DOM pass; returns an unsubscribe function. */
      observe: function (pass) {
        var entry = { key: key, pass: pass }
        passes.push(entry)
        if (document.body !== null) request()
        return function () {
          var index = passes.indexOf(entry)
          if (index !== -1) passes.splice(index, 1)
        }
      },
      /** Ask for one sweep on the next frame. */
      schedule: request,
      /** Install or replace a sheet scoped to this component. */
      style: function (id, css) {
        return installStyle(key + '/' + id, css)
      },
      /** Current text of one of this component's sheets. */
      styleText: function (id) {
        var style = sheetById(key + '/' + id)
        return style === null ? '' : style.textContent
      },
      /** A token's computed value; components should prefer the CSS variable. */
      token: function (name, fallback) {
        try {
          var scope = document.body !== null ? document.body : root
          var value = getComputedStyle(scope).getPropertyValue(name).trim()
          if (value !== '') return value
        } catch (error) {
          fail(key, error)
        }
        return fallback === undefined ? '' : fallback
      },

      /* ---- diagnostics ------------------------------------------------ */
      log: function (message) {
        console.info('[ui-copy/' + key + '] ' + message)
      },
      warn: function (message) {
        warn(key, message)
      },
      error: function (error) {
        fail(key, error)
      },
    }
  }

  /**
   * Register a component and hand it the runtime.
   *
   * Enabled is the config's `enabled` when it is a boolean and `true` when the
   * profile says nothing, so a component that ships enabled keeps working after
   * an upgrade that adds a sibling and the user turns things off one by one.
   */
  function mount(key, factory) {
    var options = componentConfig(key)
    var record = {
      key: key,
      enabled: options.enabled === false ? false : true,
      options: options,
    }
    components[key] = record
    if (!record.enabled) return
    if (typeof factory !== 'function') {
      warn(key, 'no factory for this component')
      return
    }
    try {
      factory(componentApi(key, options))
    } catch (error) {
      record.enabled = false
      fail(key, error)
    }
  }

  var observer = null
  if (typeof MutationObserver === 'function') {
    observer = new MutationObserver(request)
    var start = function () {
      if (document.body === null) return
      // No `attributes`: React churns attributes constantly, and a component
      // that writes an attribute from a pass would re-enter itself through the
      // observer. Every surface this suite patches is created or replaced as a
      // node, so childList plus characterData is the whole trigger set.
      observer.observe(document.body, { childList: true, subtree: true, characterData: true })
      request()
    }
    if (document.body !== null) start()
    else document.addEventListener('DOMContentLoaded', start, { once: true })
    cleanups.push(function () {
      observer.disconnect()
    })
  }

  /** Remove every pass, sheet and observer this runtime owns. */
  function dispose() {
    passes.length = 0
    for (var index = 0; index < cleanups.length; index += 1) {
      try {
        cleanups[index]()
      } catch (error) {
        /* a failed cleanup must not stop the rest */
      }
    }
    cleanups.length = 0
  }

  var base = componentApi('runtime', {})
  return {
    ctx: ctx,
    config: suiteConfig,
    require: requireExternal,
    mount: mount,
    component: base.component,
    observe: base.observe,
    schedule: base.schedule,
    style: base.style,
    token: base.token,
    theme: base.theme,
    dispose: dispose,
  }
}

/* ---- component -------------------------------------------------------- */

/**
 * dsh-ui-ptc — 浏览器半边。
 *
 * PTC 模式把一次程序执行画成一棵调用树：根是 run_code，程序里每次
 * tools.xxx() 都是它的子调用。内置的根行是一张通用的代码卡片，于是聊天里
 * 先出现一大段代码，真正的动作缩在它下面的竖线里。
 *
 * 这一层只改根行：把 run_code 自己的卡片从 tool.call.toolview 上摘下来，
 * 子调用列去掉缩进与竖线，动作就像普通模式那样平铺在聊天里。
 *
 * 根行只在两种情况下保留一行字：程序没有派发任何子调用（否则这一段会整段
 * 空掉），以及程序本身失败、中止或超时（错误不在任何子调用里，不能让它们
 * 静默消失）。
 */

function dshuiComponent_ptc(rt) {
  const React = rt.require('react')
  if (React === null || typeof React.createElement !== 'function') {
    rt.warn('react is not in this boot graph; component skipped')
    return
  }

  const h = React.createElement
  const Fragment = React.Fragment

  /** The keyed Tool view seat this component owns. */
  const TOOLVIEW_SLOT = 'tool.call.toolview'

  /** Our own markers: the root marker also tells the stylesheet which row lost its card. */
  const ROOT_ATTR = 'data-dshui-ptc-root'
  const ROW_ATTR = 'data-dshui-ptc-row'
  const RUNNING_ATTR = 'data-dshui-ptc-running'
  const FAILED_ATTR = 'data-dshui-ptc-failed'
  const ROOT_CLASS = 'dshui-ptc-root'
  const NOTE_CLASS = 'dshui-ptc-note'
  const ERROR_CLASS = 'dshui-ptc-error'

  /* The stylesheet spells the row marker literally; keep it in sync with ROW_ATTR. */
  const STYLESHEET = `
/* The card itself is gone; this span only carries the row marker. */
.dshui-ptc-root {
  display: none;
}

/* The call row that lost its card: its children stand on their own now. */
[data-dshui-ptc-row] > [data-subcalls] {
  position: relative;
  margin: 0;
  padding-left: 8px;
  border-left: 0;
}

/* The group keeps a whisper of the guide line: 1px, dimmed, clear on hover. */
[data-dshui-ptc-row] > [data-subcalls]::before {
  content: '';
  position: absolute;
  left: 0;
  top: 3px;
  bottom: 3px;
  width: 1px;
  border-radius: 1px;
  background: var(--dsw-alias-border-l2);
  opacity: 0.35;
  transition: opacity 120ms ease, background-color 120ms ease;
}

[data-dshui-ptc-row]:hover > [data-subcalls]::before {
  opacity: 0.8;
}

/* Any failed step turns the whole group's line red. */
[data-dshui-ptc-row][data-dshui-ptc-failed] > [data-subcalls]::before {
  background: var(--dsw-alias-state-error-primary);
  opacity: 0.7;
}

/* A 2px sweep across the group head while the program is still running. */
[data-dshui-ptc-row][data-dshui-ptc-running]::before {
  content: '';
  display: block;
  height: 2px;
  margin: 0 0 6px;
  border-radius: 1px;
  background-image: linear-gradient(90deg, transparent, var(--dsw-alias-state-business-primary), transparent);
  background-size: 45% 100%;
  background-repeat: no-repeat;
  animation: dshui-ptc-sweep 1.6s cubic-bezier(0.4, 0, 0.2, 1) infinite;
}

@keyframes dshui-ptc-sweep {
  0% { background-position: -45% 0; opacity: 0.35; }
  45% { opacity: 0.75; }
  100% { background-position: 100% 0; opacity: 0.35; }
}

@media (prefers-reduced-motion: reduce) {
  [data-dshui-ptc-row][data-dshui-ptc-running]::before {
    animation: none;
    opacity: 0.5;
  }
}

/* One quiet line for a program that dispatched nothing, or failed as a whole. */
.dshui-ptc-note,
.dshui-ptc-error {
  font-size: var(--dsh-content-font-size-secondary, 13px);
  line-height: 1.5;
  margin: 2px 0;
  padding: 0;
  overflow-wrap: anywhere;
}

.dshui-ptc-note {
  color: var(--dsw-alias-label-secondary);
}

.dshui-ptc-error {
  color: var(--dsw-alias-state-error-primary);
}
`

  /** Whether the block is a settled result (its stage left the event stream). */
  function settled(block) {
    return typeof block === 'object' && block !== null && 'kind' in block
  }

  /** Whether one dispatched step settled as a failure or a stop. */
  function childFailed(block) {
    if (!settled(block)) return false
    if (block.isError === true) return true
    return typeof block.error === 'object' && block.error !== null && block.error.code === 'interrupted'
  }

  /** The result's text content, flattened the same way the built-in rows do it. */
  function resultText(node) {
    const parts = []
    const content = Array.isArray(node === null || node === undefined ? null : node.content) ? node.content : []
    for (let index = 0; index < content.length; index += 1) {
      const block = content[index]
      if (block !== null && typeof block === 'object' && block.type === 'text' && typeof block.text === 'string') {
        parts.push(block.text)
        continue
      }
      try {
        parts.push(JSON.stringify(block, null, 2))
      } catch (error) {
        parts.push(String(block))
      }
    }
    return parts.join('\n')
  }

  /** First non-empty line of a text, trimmed. */
  function firstLine(text) {
    const lines = String(text).split('\n')
    for (let index = 0; index < lines.length; index += 1) {
      const line = lines[index].trim()
      if (line !== '') return line
    }
    return ''
  }

  /** The whole-program failure: its text, else its error code. Empty means "no detail". */
  function failureLine(block) {
    const error = typeof block.error === 'object' && block.error !== null ? block.error : null
    const text = firstLine(resultText(block))
    if (text !== '') return text
    if (error !== null) {
      if (typeof error.code === 'string' && error.code !== '') return error.code
      if (typeof error.name === 'string' && error.name !== '') return error.name
    }
    return ''
  }

  /** The model's own description of this run, when the arguments already carry one. */
  function callDescription(block) {
    try {
      const args = block === null || block === undefined ? null : block.args
      if (typeof args !== 'object' || args === null) return ''
      const value = args.description
      return typeof value === 'string' ? value.trim() : ''
    } catch (error) {
      return ''
    }
  }

  /**
   * The replacement for the run_code card.
   *
   * It renders nothing for the program itself: the subcalls are siblings this
   * seat never owns, so leaving the card empty is exactly what makes them rise
   * to the conversation flow. A row keeps one line only when there is nothing
   * else to look at, or when the failure belongs to the program and no subcall
   * will ever carry it.
   */
  function PtcRoot(props) {
    const block = props.block
    const done = settled(block)
    const subCalls = Array.isArray(block === null || block === undefined ? null : block.subCalls) ? block.subCalls : []
    const stopped = done && typeof block.error === 'object' && block.error !== null && block.error.code === 'interrupted'
    const failed = done && (block.isError === true || stopped)
    const running = !done
    const anyChildFailed = subCalls.some(childFailed)
    const rootRef = React.useRef(null)

    // The stylesheet cannot walk up from here, so the row itself is marked:
    // its child column keeps only a whisper of the guide line, and the head
    // shows a sweep while the program is still running.
    React.useEffect(function () {
      const node = rootRef.current
      if (node === null || typeof node.closest !== 'function') return undefined
      const row = node.closest('[data-chat-call-id]')
      if (row === null) return undefined
      row.setAttribute(ROW_ATTR, '')
      if (running) row.setAttribute(RUNNING_ATTR, '')
      else row.removeAttribute(RUNNING_ATTR)
      if (failed || anyChildFailed) row.setAttribute(FAILED_ATTR, '')
      else row.removeAttribute(FAILED_ATTR)
      return function () {
        row.removeAttribute(ROW_ATTR)
        row.removeAttribute(RUNNING_ATTR)
        row.removeAttribute(FAILED_ATTR)
      }
    }, [running, failed, anyChildFailed])

    const children = []

    if (failed) {
      const detail = failureLine(block)
      const label = stopped ? '程序已中止' : '程序执行失败'
      children.push(
        h('div', { key: 'error', className: ERROR_CLASS, role: 'note' }, detail === '' ? label : label + ' · ' + detail),
      )
    } else if (subCalls.length === 0 && props.phase !== 'preparing') {
      const description = callDescription(block)
      const label = done ? '程序已完成' : '程序运行中'
      children.push(
        h('div', { key: 'note', className: NOTE_CLASS }, description === '' ? label : label + ' · ' + description),
      )
    }

    children.push(
      h('span', {
        key: 'root',
        ref: rootRef,
        className: ROOT_CLASS,
        [ROOT_ATTR]: 'true',
        'aria-hidden': 'true',
      }),
    )

    return h(Fragment, null, children)
  }

  /**
   * Install the sheet and claim the run_code seat.
   *
   * The seat is keyed and empty in the shipped composition, so a plain
   * registration wins over the generic fallback without a priority override.
   */
  function install(ctx) {
    rt.effect(function () {
      const removeSheet = rt.style('ptc', STYLESHEET)
      let offToolview = null
      try {
        offToolview = ctx.slots.inject(TOOLVIEW_SLOT, function () {
          // The shipped ui-tool registers the same key at priority 0; the
          // lowest priority renders, so this row must claim a lower number.
          return ctx.slots.register({ name: TOOLVIEW_SLOT, key: 'run_code', priority: -1 }, PtcRoot)
        })
      } catch (error) {
        // No conversation layer in this composition: leave no dangling sheet.
        rt.error(error)
      }
      return function () {
        if (offToolview !== null) offToolview()
        removeSheet()
      }
    }, 'ui-ptc: run_code row')
  }

  rt.ctx.inject(['slots'], function (scope) {
    install(scope)
  })
}

/* ---- entry ------------------------------------------------------------ */

window.__ModuleLoader__.load({
  // The boot-graph row id is the package name; client-modules serves this file
  // at `/plugins/<包名>/client.js` and keys the factory by the same string.
  id: 'dsh-ui-ptc',
  factory: (require) => {
    const module = { exports: {} }
    const exports = module.exports
    Object.defineProperty(exports, Symbol.toStringTag, { value: 'Module' })

    /**
     * Mount this package's component on its own runtime.
     *
     * The host half injects this row's configuration as `window.DSHUI_PTC`
     * before the boot graph runs, because a boot-graph row arrives as
     * `{ id, url, rev }` and `apply(ctx, config)` always sees an empty config.
     */
    function apply(ctx) {
      const injected = window.DSHUI_PTC
      const config = typeof injected === 'object' && injected !== null ? injected : {}
      const runtime = dshuiCreateRuntime({ ctx, require }, { 'ptc': config })
      runtime.mount('ptc', dshuiComponent_ptc)
      exports.runtime = runtime
      return function dispose() {
        runtime.dispose()
      }
    }

    exports.apply = apply
    exports.inject = []
    return module.exports
  },
})
